// Live Session Assistant — Beads hierarchy spec (single source for validation, docs tables, and creation).
// Keys are relative to the epic ("EPIC", "1", "1.4", "1.4.1"). External beads use "ext:<suffix>"
// where suffix is the part after "agent-forge-harness-". Text references to plan beads use "LSA-<key>"
// and are substituted with created ids at materialization.
// Revision 2: applies plan review turn 1 (docs/forge/reports/live-session-assistant-plan-review.md),
// the Workbench decision record (PR #58), and the legal/market/speech research.
// Revision 3: applies plan review turn 2 (docs/forge/reports/live-session-assistant-plan-review-2.md).
// Revision 4: applies the independent verification of the turn-2 resolutions (same report).
// Materialized on 2026-09-17 as epic agent-forge-harness-1ir (ids.json). From then on the Beads tracker is
// authoritative: this file records what was created, and verify-created.ts reports drift from it.

export type BeadType = 'epic' | 'feature' | 'task' | 'decision'
export interface Bead {
  key: string
  parent?: string
  type: BeadType
  priority: 0 | 1 | 2 | 3
  phase: 0 | 1 | 2 | 3 | 4 | 5 | null
  title: string
  description: string
  design?: string
  acceptance: string
  labels?: string[]
  blockedBy?: string[] // local keys or ext refs this bead depends on
  blocks?: string[] // ext refs that depend on this bead (edges into other initiatives)
  relatesTo?: string[]
  gate?: number // phase number this gate approves
  postGate?: number // enablement bead that must follow gate N
  gateExempt?: string // reason a leaf is not required by its phase gate
}

